import{_ as l,a0 as i,w as o,s as r,ao as d,I as p,x as e,a1 as s,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"使用 apt-get 清理 | LCTT x X-CMD","titleTemplate":false,"description":"使用 apt-get 清理 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 apt-get 清理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 apt-get 清理 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191114 Cleaning up with apt-get","title":"使用 apt-get 清理","tag":"201911","desc":""},"relativePath":"201911/20191114 Cleaning up with apt-get.md","filePath":"[post].md"}'),c={name:"201911/20191114 Cleaning up with apt-get.md"};function g(h,a,u,b,m,k){const t=i("Link");return o(),r("div",null,[a[15]||(a[15]=d(`<h1 id="使用-apt-get-清理" tabindex="-1">使用 apt-get 清理 <a class="header-anchor" href="#使用-apt-get-清理" aria-label="Permalink to “使用 apt-get 清理”">​</a></h1><blockquote><p>大多数使用基于 Debian 的系统的人通常会使用 apt-get 来安装软件包和升级，但是我们多久才清理一次？让我们看下该工具本身的一些清理选项。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201911/22/082025p39oeuufdote517e.jpg" alt=""></p><p>在基于 Debian 的系统上运行 <code>apt-get</code> 命令是很常规的。软件包的更新相当频繁，诸如 <code>apt-get update</code> 和 <code>apt-get upgrade</code> 之类的命令使此过程非常容易。另一方面，你多久使用一次 <code>apt-get clean</code>、<code>apt-get autoclean</code> 或 <code>apt-get autoremove</code>？</p><p>这些命令会在 <code>apt-get</code> 的安装操作后清理并删除仍在系统上但不再需要的文件，这通常是因为需要它们的程序已经卸载。</p><h3 id="apt-get-clean" tabindex="-1">apt-get clean <a class="header-anchor" href="#apt-get-clean" aria-label="Permalink to “apt-get clean”">​</a></h3><p><code>apt-get clean</code> 命令清除遗留在 <code>/var/cache</code> 中的已取回的包文件的本地仓库。它清除的目录是 <code>/var/cache/apt/archives/</code> 和 <code>/var/cache/apt/archives/partial/</code>。它留在 <code>/var/cache/apt/archives</code> 中的唯一文件是 <code>lock</code> 文件和 <code>partial</code> 子目录。</p><p>在运行清理操作之前，目录中可能包含许多文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/var/cache/apt/archives/db5.3-util_5.3.28+dfsg1-0.6ubuntu1_amd64.deb</span></span>
<span class="line"><span>/var/cache/apt/archives/db-util_1%3a5.3.21~exp1ubuntu2_all.deb</span></span>
<span class="line"><span>/var/cache/apt/archives/lock</span></span>
<span class="line"><span>/var/cache/apt/archives/postfix_3.4.5-1ubuntu1_amd64.deb</span></span>
<span class="line"><span>/var/cache/apt/archives/sasl2-bin_2.1.27+dfsg-1build3_amd64.deb</span></span></code></pre></div><p>之后，只会存在这些：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ls -lR /var/cache/apt/archives</span></span>
<span class="line"><span>/var/cache/apt/archives:</span></span>
<span class="line"><span>total 4</span></span>
<span class="line"><span>-rw-r----- 1 root root    0 Jan  5  2018 lock</span></span>
<span class="line"><span>drwx------ 2 _apt root 4096 Nov 12 07:24 partial</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/var/cache/apt/archives/partial:</span></span>
<span class="line"><span>total 0                 &lt;== 空</span></span></code></pre></div><p><code>apt-get clean</code> 命令通常用于根据需要清除磁盘空间，一般作为定期计划维护的一部分。</p><h3 id="apt-get-autoclean" tabindex="-1">apt-get autoclean <a class="header-anchor" href="#apt-get-autoclean" aria-label="Permalink to “apt-get autoclean”">​</a></h3><p><code>apt-get autoclean</code> 类似于 <code>apt-get clean</code>，它会清除已检索包文件的本地仓库，但它只会删除不会再下载且几乎无用的文件。它有助于防止缓存过大。</p><h3 id="apt-get-autoremove" tabindex="-1">apt-get autoremove <a class="header-anchor" href="#apt-get-autoremove" aria-label="Permalink to “apt-get autoremove”">​</a></h3><p><code>apt-get autoremove</code> 将删除自动安装的软件包，因为某些其他软件包需要它们，但是在删除了其他软件包之后，而不再需要它们。有时会在升级时建议运行此命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>The following packages were automatically installed and are no longer required:</span></span>
<span class="line"><span>  g++-8 gir1.2-mutter-4 libapache2-mod-php7.2 libcrystalhd3</span></span>
<span class="line"><span>  libdouble-conversion1 libgnome-desktop-3-17 libigdgmm5 libisl19 libllvm8</span></span>
<span class="line"><span>  liblouisutdml8 libmutter-4-0 libmysqlclient20 libpoppler85 libstdc++-8-dev</span></span>
<span class="line"><span>  libtagc0 libvpx5 libx265-165 php7.2 php7.2-cli php7.2-common php7.2-json</span></span>
<span class="line"><span>  php7.2-opcache php7.2-readline</span></span>
<span class="line"><span>Use &#39;sudo apt autoremove&#39; to remove them.                       &lt;==</span></span></code></pre></div><p>要删除的软件包通常称为“未使用的依赖项”。实际上，一个好的做法是在卸载软件包后使用 <code>autoremove</code>，以确保不会留下不需要的文件。</p><hr>`,19)),p("p",null,[a[1]||(a[1]=e("via: ",-1)),s(t,{href:"https://www.networkworld.com/article/3453032/cleaning-up-with-apt-get.html"},{default:n(()=>[...a[0]||(a[0]=[e("https://www.networkworld.com/article/3453032/cleaning-up-with-apt-get.html",-1)])]),_:1})]),p("p",null,[a[6]||(a[6]=e("作者：",-1)),s(t,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...a[2]||(a[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),a[7]||(a[7]=e(" 选题：",-1)),s(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...a[3]||(a[3]=[e("lujun9972",-1)])]),_:1}),a[8]||(a[8]=e(" 译者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:n(()=>[...a[4]||(a[4]=[e("geekpi",-1)])]),_:1}),a[9]||(a[9]=e(" 校对：",-1)),s(t,{href:"https://github.com/wxy"},{default:n(()=>[...a[5]||(a[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[a[12]||(a[12]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[10]||(a[10]=[e("LCTT",-1)])]),_:1}),a[13]||(a[13]=e(" 原创编译，",-1)),s(t,{href:"https://linux.cn/"},{default:n(()=>[...a[11]||(a[11]=[e("Linux中国",-1)])]),_:1}),a[14]||(a[14]=e(" 荣誉推出",-1))])])}const x=l(c,[["render",g]]);export{w as __pageData,x as default};
